/*
 * Reimplementation of FIGlet (character figures) command.
 *
 * Implements the behavior of the reference binary as observed from
 * its documentation and interactive experiments.
 */
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <wchar.h>

#define DEFAULT_FONTDIR    "/usr/local/share/figlet"
#define DEFAULT_FONT       "standard"
#define DEFAULT_COLUMNS    80
#define MAX_INPUT_LINE     16384

/* Smushmode bits */
#define SM_EQUAL      1
#define SM_LOWLINE    2
#define SM_HIERARCHY  4
#define SM_PAIR       8
#define SM_BIGX       16
#define SM_HARDBLANK  32
#define SM_KERN       64
#define SM_SMUSH      128

/* Justification */
#define SMO_NO        0   /* smush off (full width) */
#define SMO_YES       1   /* smush according to font's smushmode */
#define SMO_FORCE     2   /* force smush */

/* Right-to-left: 0=LTR, 1=RTL, 2=default (from font) */
#define RTL_LTR       0
#define RTL_RTL       1
#define RTL_DEFAULT   2

/* Justification: 0=LTR-default,1=center,2=right, -1 = use RTL default */
#define JUST_DEFAULT  -1
#define JUST_LEFT     0
#define JUST_CENTER   1
#define JUST_RIGHT    2

/* global program name used for error messages */
static const char *progname = "figlet";

/* Font data */
typedef struct FigChar {
    int code;
    char **lines;   /* charheight strings, stored as bytes.  Each line ends at '\0' */
    int width;
    struct FigChar *next;
} FigChar;

typedef struct Font {
    char hardblank;
    int charheight;
    int maxlen;
    int oldlayout;
    int cmtlines;
    int right2left;
    int fulllayout;
    int codetagcount;
    int has_full_layout;   /* non-zero if full_layout field was present in the header */
    int smushmode;         /* effective smushmode (derived from fulllayout or oldlayout) */
    FigChar *chars;        /* linked list of characters */
} Font;

/* Options parsed */
static int  opt_smushoverride = 0;     /* 0=normal,1=-s,2=-S */
static int  opt_smushmode = 0;         /* user-requested smushmode (via -m) */
static int  opt_smushuser = 0;         /* user gave -m/k/W/o/s/S */
static int  opt_deutsch = 0;
static int  opt_paragraph = 0;
static int  opt_outputwidth = DEFAULT_COLUMNS;
static int  opt_outputwidth_user = 0;
static int  opt_useterminalwidth = 0;
static int  opt_right2left = RTL_DEFAULT;
static int  opt_justification = JUST_DEFAULT;
static int  opt_infocode = -1;
static char *opt_fontname = NULL;
static char *opt_fontdir = NULL;

/* Control file list */
typedef struct CFile {
    char *path;
    struct CFile *next;
} CFile;
static CFile *cfiles = NULL;
static CFile *cfiles_tail = NULL;

/* Translation/control loaded data */
typedef struct Trans {
    int from;     /* single char; <0 means range start */
    int to;
    int from_end; /* if from is a range, this is end of from range */
    int to_end;   /* corresponding end of to range */
    int is_range; /* 1 if this is a range translation */
    struct Trans *next;
} Trans;

static Trans *global_trans = NULL;
static Trans *global_trans_tail = NULL;
static int   input_mode = 0; /* 0=Latin-1, 'u'=UTF-8, etc. */

static void add_cfile(const char *path) {
    CFile *c = malloc(sizeof(CFile));
    c->path = strdup(path);
    c->next = NULL;
    if (cfiles_tail) cfiles_tail->next = c;
    else cfiles = c;
    cfiles_tail = c;
}

static void clear_cfiles(void) {
    CFile *c = cfiles;
    while (c) {
        CFile *n = c->next;
        free(c->path);
        free(c);
        c = n;
    }
    cfiles = cfiles_tail = NULL;
}

/* Die with error. */
static void die(const char *fmt, ...) {
    va_list ap;
    fprintf(stderr, "%s: ", progname);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fprintf(stderr, "\n");
    exit(1);
}

CEOF
