/*
 * Standard FIGfont Deutsch character codes (in order)
 */
static const int deutsch_codes[7] = {196,214,220,228,246,252,223};

static void print_usage_error(const char *optstr) {
    /* prints the "invalid option --" message with argv0, then usage */
    /* The reference uses argv[0] prefix for the "invalid option" message. */
    fprintf(stderr, "./%s: invalid option -- '%s'\n", progname, optstr);
}

static void print_usage(FILE *f) {
    fprintf(f,
        "Usage: %s [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n"
        "              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n"
        "              [ -C controlfile ] [ -I infocode ] [ message ]\n",
        progname);
}

static void print_version(FILE *f) {
    fprintf(f,
        "FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,\n"
        "Christiaan Keet and Claudio Matsuoka\n"
        "Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012\n"
        "\n"
        "FIGlet, along with the various FIGlet fonts and documentation, may be\n"
        "freely copied and distributed.\n"
        "\n"
        "If you use FIGlet, please send an e-mail message to <info@figlet.org>.\n"
        "\n"
        "The latest version of FIGlet is available from the web site,\n"
        "\thttp://www.figlet.org/\n"
        "\n");
    print_usage(f);
}

/* Read a line from FILE into a malloc'd buffer.  Returns NULL on EOF. */
static char *read_line(FILE *f) {
    size_t cap = 128;
    size_t len = 0;
    char *buf = malloc(cap);
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (len + 2 > cap) {
            cap *= 2;
            buf = realloc(buf, cap);
        }
        if (c == '\n') break;
        buf[len++] = (char)c;
    }
    if (c == EOF && len == 0) { free(buf); return NULL; }
    buf[len] = '\0';
    return buf;
}

/* Try to open a file.  If the name contains '/', try as-is and with ".flf"/".flc".
 * Otherwise, search in dir first then current dir; both with and without extension.
 * Returns opened FILE* or NULL.
 */
static FILE *open_by_name(const char *name, const char *dir, const char *ext) {
    char path[4096];
    FILE *f;

    if (strchr(name, '/')) {
        /* try as-is */
        if ((f = fopen(name, "r"))) return f;
        /* try with ext */
        snprintf(path, sizeof(path), "%s%s", name, ext);
        if ((f = fopen(path, "r"))) return f;
        return NULL;
    }

    /* try in dir with ext */
    if (dir && *dir) {
        snprintf(path, sizeof(path), "%s/%s%s", dir, name, ext);
        if ((f = fopen(path, "r"))) return f;
        /* try without ext */
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        if ((f = fopen(path, "r"))) return f;
    }

    /* try current dir with ext */
    snprintf(path, sizeof(path), "%s%s", name, ext);
    if ((f = fopen(path, "r"))) return f;

    /* try current dir without ext */
    if ((f = fopen(name, "r"))) return f;

    return NULL;
}

