       but we have already stripped that prefix before calling.  Here 'line'
       starts with the hardblank char (possibly space). */
    if (!line) return -1;
    const char *p = line;
    /* Skip leading spaces - but the hardblank should be right there */
    if (*p == '\0') return -1;
    ft->hardblank = *p++;
    /* Skip any spaces */
    while (*p == ' ') p++;

    int got;
    int height=-1, baseline=-1, maxlen=-1, oldlayout=INT_MIN, cmtlines=-1;
    int pdir=-1, fulllayout=-1, ctc=-1;

    /* Parse integers */
    int n = sscanf(p, "%d %d %d %d %d %d %d %d",
                   &height, &baseline, &maxlen, &oldlayout, &cmtlines,
                   &pdir, &fulllayout, &ctc);
