    ft->charheight = height;
    ft->maxlen = maxlen;
    ft->oldlayout = oldlayout;
    ft->cmtlines = cmtlines;
    ft->right2left = (n >= 6) ? pdir : 0;
    if (n >= 7) {
        ft->has_full_layout = 1;
        ft->fulllayout = fulllayout;
    } else {
        ft->has_full_layout = 0;
        ft->fulllayout = -1;
    }
    ft->codetagcount = (n >= 8) ? ctc : 0;
    return 0;
