        int len = (int)strlen(fc->lines[i]);
        if (len < maxw) {
            char *nl = malloc(maxw+1);
            memcpy(nl, fc->lines[i], len);
            for (int k = len; k < maxw; k++) nl[k] = ' ';
            nl[maxw] = '\0';
            free(fc->lines[i]);
            fc->lines[i] = nl;
        }
    }
    fc->width = maxw;
    return fc;
