/*
 * Smushing rules for horizontal smushing.
 * Try to smush two subchars.  Returns the smushed char,
 * or 0 if they cannot be smushed.
 *
 * left  - the left char
 * right - the right char
 * smushmode - active smushmode (bits SM_*)
 * hardblank - the font's hardblank
 * right2left - 0 for LTR, 1 for RTL (affects hierarchy rule direction)
 */
static int smushem(int left, int right, int smushmode, char hardblank, int right2left) {
    if (left == ' ') return right;
    if (right == ' ') return left;

    /* Hardblank handling: if both are hardblank */
    if (left == (unsigned char)hardblank || right == (unsigned char)hardblank) {
        if (!(smushmode & SM_SMUSH)) return 0; /* kerning only */
        if (smushmode & SM_HARDBLANK) {
            if (left == (unsigned char)hardblank && right == (unsigned char)hardblank) {
                return left; /* smush two hardblanks */
            }
        }
        return 0; /* hardblank doesn't smush with regular char by default */
    }

    /* Kerning: no smushing, but chars don't overlap. */
    if (!(smushmode & SM_SMUSH)) {
        return 0;
    }

    /* Universal smushing: no specific rules selected */
    if ((smushmode & 63) == 0) {
        if (right2left) return left; else return right;
    }

    /* Rule 1: equal character */
    if (smushmode & SM_EQUAL) {
        if (left == right) return left;
    }
    /* Rule 2: underscores */
    if (smushmode & SM_LOWLINE) {
        const char *under = "|/\\[]{}()<>";
        if (left == '_' && strchr(under, right)) return right;
        if (right == '_' && strchr(under, left)) return left;
    }
    /* Rule 3: hierarchy */
    if (smushmode & SM_HIERARCHY) {
        const char *classes[] = {"|", "/\\", "[]", "{}", "()", "<>", NULL};
        int lc = -1, rc = -1;
        for (int i = 0; classes[i]; i++) {
            if (strchr(classes[i], left)) lc = i;
            if (strchr(classes[i], right)) rc = i;
        }
        if (lc != -1 && rc != -1 && lc != rc) {
            return (lc > rc) ? left : right;
        }
    }
    /* Rule 4: opposite pair */
    if (smushmode & SM_PAIR) {
        if ((left == '[' && right == ']') || (left == ']' && right == '[')) return '|';
        if ((left == '{' && right == '}') || (left == '}' && right == '{')) return '|';
        if ((left == '(' && right == ')') || (left == ')' && right == '(')) return '|';
    }
    /* Rule 5: big X */
    if (smushmode & SM_BIGX) {
        if (left == '/' && right == '\\') return '|';
        if (left == '\\' && right == '/') return 'Y';
        if (left == '>' && right == '<') return 'X';
    }
    return 0;
}

/*
 * Compute smush amount: how many columns can be overlapped
 * when placing fc to the right of current_lines.
 *
 * current_lines[r] is the current output buffer row (strings of bytes).
 * fc is the new figchar.
 */
static int smushamt(char **current, int *curwidths, int curheight,
                    FigChar *fc, int smushmode, char hardblank, int right2left)
{
    int maxsmush = fc->width;
    int h = curheight;

    for (int r = 0; r < h; r++) {
        int curlen = curwidths[r];
        const char *cur = current[r];
        const char *newf = fc->lines[r];
        int newlen = fc->width;

        /* Find left-space amount on new line (leading spaces of new char) */
        int left_sp;
        for (left_sp = 0; left_sp < newlen && newf[left_sp] == ' '; left_sp++) ;

        /* Find right-space amount on current line (trailing spaces) */
        int right_sp;
        for (right_sp = 0; right_sp < curlen && cur[curlen - 1 - right_sp] == ' '; right_sp++) ;

        int amt = left_sp + right_sp;

        /* Try to smush one more character */
        int ch1 = (curlen - right_sp > 0) ? (unsigned char)cur[curlen - right_sp - 1] : 0;
        int ch2 = (left_sp < newlen) ? (unsigned char)newf[left_sp] : 0;
        if (ch1 == 0 || ch2 == 0) {
            /* Can overlap entire width */
            if (amt > maxsmush) { /* don't constrain here; limit later */ }
        } else {
            int s = smushem(ch1, ch2, smushmode, hardblank, right2left);
            if (s != 0) amt += 1;
        }
        if (amt < maxsmush) maxsmush = amt;
    }
    return maxsmush;
}

