/*
 * Line accumulator.
 *
 * outline[] - committed output (all rows same length = outlinelen)
 * inchline[] - current word being built (all rows same length = inchlinelen)
 *
 * Both are padded to the row length with spaces.
 */
typedef struct Line {
    char **rows;   /* charheight rows */
    int len;
    int cap;
    int height;
