static void line_init(Line *l, int height) {
    l->height = height;
    l->len = 0;
    l->cap = 256;
    l->rows = calloc(height, sizeof(char*));
    for (int i = 0; i < height; i++) {
        l->rows[i] = malloc(l->cap);
        l->rows[i][0] = '\0';
    }
}

static void line_ensure(Line *l, int need) {
    if (need + 1 > l->cap) {
        while (l->cap < need + 1) l->cap *= 2;
        for (int i = 0; i < l->height; i++) {
            l->rows[i] = realloc(l->rows[i], l->cap);
        }
    }
}

static void line_clear(Line *l) {
    l->len = 0;
    for (int i = 0; i < l->height; i++) l->rows[i][0] = '\0';
