/* Emit a completed line with justification and hardblank replacement. */
static void emit_line(Line *out, int outputwidth, int justification, char hardblank, int right2left) {
    if (out->len == 0) {
        /* Empty line - output empty lines for each row */
        for (int r = 0; r < out->height; r++) {
            putchar('\n');
        }
        return;
    }
    int pad = 0;
    if (justification == JUST_CENTER) {
        pad = (outputwidth - out->len) / 2;
        if (pad < 0) pad = 0;
    } else if (justification == JUST_RIGHT) {
        pad = outputwidth - out->len;
        if (pad < 0) pad = 0;
    }
    for (int r = 0; r < out->height; r++) {
        for (int k = 0; k < pad; k++) putchar(' ');
        for (int c = 0; c < out->len; c++) {
            int ch = (unsigned char)out->rows[r][c];
            if (ch == (unsigned char)hardblank) putchar(' ');
            else putchar(ch);
        }
        putchar('\n');
    }
    line_clear(out);
}

