/*
 * Reverse each row of a line in place (for RTL mode).
 * Used to mirror RTL output once it's built (if needed).
 */
static void line_reverse_rows(Line *l) {
    for (int r = 0; r < l->height; r++) {
        int n = l->len;
        char *s = l->rows[r];
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            char t = s[i]; s[i] = s[j]; s[j] = t;
        }
    }
}

