/*
 * Input character translation from control file list.
 * Returns the translated character.
 */
static int translate_char(int c) {
    if (opt_deutsch) {
        switch (c) {
            case '[':  c = 196; break;  /* Ä */
            case '\\': c = 214; break;  /* Ö */
            case ']':  c = 220; break;  /* Ü */
            case '{':  c = 228; break;  /* ä */
            case '|':  c = 246; break;  /* ö */
            case '}':  c = 252; break;  /* ü */
            case '~':  c = 223; break;  /* ß */
        }
    }
    for (Trans *t = global_trans; t; t = t->next) {
        if (t->is_range) {
            if (c >= t->from && c <= t->from_end) {
                int off = c - t->from;
                int target = t->to + off;
                /* If target range is shorter, wrap to last */
                if (off > (t->to_end - t->to)) target = t->to_end;
                c = target;
            }
        } else {
            if (c == t->from) c = t->to;
        }
    }
    return c;
}

/*
 * Parse a single control-file translation token.
 * Recognized tokens:
 *   A single character (possibly escaped: \a, \b, \e, \f, \n, \r, \t, \v, \\, \' , \"  )
 *   \NNN where NNN is decimal
 *   \0NNN where NNN is octal
 *   \0xNNN where NNN is hex
 *   \-NNN where NNN means subtract (to make negative signed offset unused here)
 *
 * Returns the number of bytes consumed from *p and stores the char in *out.
 * Returns -1 if no valid token.
 */
static int parse_escape(const char *p, int *out) {
    if (*p == '\0') return -1;
    if (*p != '\\') {
        *out = (unsigned char)*p;
        return 1;
    }
    p++;
    /* after backslash */
    int used = 1;
    int ch = 0;
    if (*p == '\0') { *out = '\\'; return 1; }
    switch (*p) {
        case 'a': *out = '\a'; return 2;
        case 'b': *out = '\b'; return 2;
        case 'e': *out = 27; return 2;
        case 'f': *out = '\f'; return 2;
        case 'n': *out = '\n'; return 2;
        case 'r': *out = '\r'; return 2;
        case 't': *out = '\t'; return 2;
        case 'v': *out = '\v'; return 2;
        case '\\': *out = '\\'; return 2;
        case '\'': *out = '\''; return 2;
        case '"': *out = '"'; return 2;
        case '-': {
            /* negative: skip */
            int sign = -1;
            used = 2;
            p++;
            if (*p == '0' && (p[1] == 'x' || p[1] == 'X')) {
                char *end;
                ch = strtol(p, &end, 16);
                used += (end - p);
                *out = sign * ch;
                return used;
            } else if (*p == '0') {
                char *end;
                ch = strtol(p, &end, 8);
                used += (end - p);
                *out = sign * ch;
                return used;
            } else if (isdigit((unsigned char)*p)) {
                char *end;
                ch = strtol(p, &end, 10);
                used += (end - p);
                *out = sign * ch;
                return used;
            }
            *out = '-';
            return used;
        }
        case '0': {
            /* octal or hex */
            if (p[1] == 'x' || p[1] == 'X') {
                char *end;
                ch = strtol(p, &end, 16);
                used = 1 + (end - p);
                *out = ch;
                return used;
            }
            char *end;
            ch = strtol(p, &end, 8);
            used = 1 + (end - p);
            *out = ch;
            return used;
        }
        default:
            if (isdigit((unsigned char)*p)) {
                char *end;
                ch = strtol(p, &end, 10);
                used = 1 + (end - p);
                *out = ch;
                return used;
            }
            /* Unknown escape: return the literal next char. */
            *out = (unsigned char)*p;
            return 2;
    }
}

/*
 * Add a single t-style translation token.  Supports range syntax "a-z".
 */
static void add_trans_tokens(const char *fromtok, const char *totok) {
    /* Parse the from token into single char or range */
    int from_start = 0, from_end = 0;
    int to_start = 0, to_end = 0;
    int from_is_range = 0, to_is_range = 0;

    int n1 = parse_escape(fromtok, &from_start);
    if (n1 <= 0) return;
    if (fromtok[n1] == '-' && fromtok[n1+1] != '\0') {
        int n2 = parse_escape(fromtok + n1 + 1, &from_end);
        if (n2 > 0) from_is_range = 1;
    } else {
        from_end = from_start;
    }

    int m1 = parse_escape(totok, &to_start);
    if (m1 <= 0) return;
    if (totok[m1] == '-' && totok[m1+1] != '\0') {
        int m2 = parse_escape(totok + m1 + 1, &to_end);
        if (m2 > 0) to_is_range = 1;
    } else {
        to_end = to_start;
    }

    Trans *t = calloc(1, sizeof(Trans));
    if (from_is_range || to_is_range) {
        t->is_range = 1;
        t->from = from_start;
        t->from_end = from_end;
        t->to = to_start;
        t->to_end = to_end;
    } else {
        t->is_range = 0;
        t->from = from_start;
        t->to = to_start;
    }
    t->next = NULL;
    if (global_trans_tail) global_trans_tail->next = t;
    else global_trans = t;
    global_trans_tail = t;
}

static int load_controlfile(const char *path) {
    FILE *f = open_by_name(path, opt_fontdir ? opt_fontdir : DEFAULT_FONTDIR, ".flc");
    if (!f) {
        fprintf(stderr, "%s: %s: Unable to open control file\n", progname, path);
        return -1;
    }
    char *hdr = read_line(f);
    if (!hdr) { fclose(f); 
        fprintf(stderr, "%s: %s: Not a FIGlet 2 control file\n", progname, path);
        return -1;
    }
    rstrip_cr(hdr);
    if (strncmp(hdr, "flc2a", 5) != 0) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 control file\n", progname, path);
        free(hdr); fclose(f);
        return -1;
    }
    free(hdr);

    char *line;
    while ((line = read_line(f))) {
        rstrip_cr(line);
        if (line[0] == '\0' || line[0] == '#') { free(line); continue; }
        char cmd = line[0];
        char *p = line + 1;
        while (*p == ' ' || *p == '\t') p++;
        if (cmd == 't') {
            /* Parse two tokens */
            char *tok1 = p;
            while (*p && *p != ' ' && *p != '\t') p++;
            if (*p == '\0') { free(line); continue; }
            *p++ = '\0';
            while (*p == ' ' || *p == '\t') p++;
            char *tok2 = p;
            while (*p && *p != ' ' && *p != '\t') p++;
            *p = '\0';
            add_trans_tokens(tok1, tok2);
        } else if (cmd == 'f') {
            /* freeze: start new translation group (all further lines compose on top) */
            /* Our implementation is linear chain; no action needed. */
        } else if (cmd == 'g') {
            /* Unused */
        } else if (cmd == 'u' || cmd == 'h' || cmd == 'j' || cmd == 's' || cmd == 'i' || cmd == 'l' || cmd == 'n') {
            /* Input mode: set */
            input_mode = cmd;
        }
        free(line);
    }
    fclose(f);
    return 0;
}

