/*
 * Render a sequence of input characters using the loaded font.
 *
 * Implements paragraph mode, word-wrapping at outputwidth, alignment,
 * and LTR/RTL.
 */
typedef struct {
    Font *ft;
    int smushmode;
    int outputwidth;
    int justification;
    int right2left;
    Line outline;
    /* For paragraph mode state: track previous char */
    int prev_char;
    int at_start;
} Renderer;

static FigChar *get_figchar(Font *ft, int c) {
    FigChar *fc = find_figchar(ft, c);
    if (!fc) fc = find_figchar(ft, 0);
    return fc;
}

static void emit_current(Renderer *r) {
    emit_line(&r->outline, r->outputwidth, r->justification, r->ft->hardblank, r->right2left);
}

/*
 * Append one figchar to the renderer.
 * Handles line overflow.
 */
static void renderer_add_fc(Renderer *r, FigChar *fc) {
    if (!fc) return;
    int w = peek_append_width(&r->outline, fc, r->smushmode, r->ft->hardblank, r->right2left);
    if (w >= r->outputwidth && r->outline.len > 0) {
        /* Would overflow. */
        emit_current(r);
        /* Now append starting from empty */
        do_append_fc(&r->outline, fc, r->smushmode, r->ft->hardblank, r->right2left);
    } else {
        do_append_fc(&r->outline, fc, r->smushmode, r->ft->hardblank, r->right2left);
    }
}

/*
 * Process a single (translated) input character.
 */
static void renderer_process(Renderer *r, int c) {
    if (c == '\n') {
        emit_current(r);
        r->prev_char = '\n';
        return;
    }
    FigChar *fc = get_figchar(r->ft, c);
    if (!fc) return;
    if (r->right2left) {
        /* For RTL, build line in reverse-byte order and reverse when emitting */
        /* Approach: swap each figchar row horizontally, smush LTR, output reversed */
        /* To achieve this, we build a temporary figchar with rows reversed. */
        FigChar tmp;
        char **rows = malloc(r->ft->charheight * sizeof(char*));
        for (int i = 0; i < r->ft->charheight; i++) {
            int w = fc->width;
            rows[i] = malloc(w + 1);
            for (int j = 0; j < w; j++) rows[i][j] = fc->lines[i][w - 1 - j];
            rows[i][w] = '\0';
        }
        tmp.code = fc->code;
        tmp.lines = rows;
        tmp.width = fc->width;
        tmp.next = NULL;
        renderer_add_fc(r, &tmp);
        for (int i = 0; i < r->ft->charheight; i++) free(rows[i]);
        free(rows);
    } else {
        renderer_add_fc(r, fc);
    }
    r->prev_char = c;
}

static void renderer_finish(Renderer *r) {
    if (r->outline.len > 0) {
        emit_current(r);
    }
}

