/*
 * Collected rendered output. Used so that we can reverse line order for RTL.
 */
typedef struct RenderedLine {
    char **rows;       /* charheight malloc'd strings (same length) */
    int len;
    int height;
    struct RenderedLine *next;
} RenderedLine;

static RenderedLine *render_head = NULL;
static RenderedLine *render_tail = NULL;

static void save_line(Line *out) {
    RenderedLine *r = calloc(1, sizeof(RenderedLine));
    r->len = out->len;
    r->height = out->height;
    r->rows = calloc(out->height, sizeof(char*));
    for (int i = 0; i < out->height; i++) {
        r->rows[i] = malloc(out->len + 1);
        memcpy(r->rows[i], out->rows[i], out->len);
        r->rows[i][out->len] = '\0';
    }
    r->next = NULL;
    if (render_tail) render_tail->next = r;
    else render_head = r;
    render_tail = r;
    line_clear(out);
}

static void reverse_render_list(void) {
    RenderedLine *prev = NULL, *cur = render_head, *next;
    while (cur) {
        next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    render_head = prev;
    render_tail = NULL;
    for (RenderedLine *r = render_head; r; r = r->next) render_tail = r;
}

static void flush_render_list(int outputwidth, int justification, char hardblank, int prepend_space) {
    for (RenderedLine *r = render_head; r; r = r->next) {
        int len = r->len;
        int pad = 0;
        int total_len = len + (prepend_space ? 1 : 0);
        if (justification == JUST_CENTER) pad = (outputwidth - total_len) / 2;
        else if (justification == JUST_RIGHT) pad = outputwidth - total_len;
        if (pad < 0) pad = 0;
        for (int i = 0; i < r->height; i++) {
            for (int k = 0; k < pad; k++) putchar(' ');
            if (prepend_space && len > 0) putchar(' ');
            for (int c = 0; c < len; c++) {
                int ch = (unsigned char)r->rows[i][c];
                if (ch == (unsigned char)hardblank) putchar(' ');
                else putchar(ch);
            }
            putchar('\n');
        }
    }
    /* Free list */
    RenderedLine *r = render_head;
    while (r) {
        RenderedLine *n = r->next;
        for (int i = 0; i < r->height; i++) free(r->rows[i]);
        free(r->rows);
        free(r);
        r = n;
    }
    render_head = render_tail = NULL;
}

