/*
 * Main rendering. Reads input one char at a time from argv or stdin,
 * and buffers output lines so that they can be reversed for RTL mode.
 */
static void render_all(Font *ft, const char *message, int have_message, char **argv_msg, int argc_msg) {
    Renderer R;
    R.ft = ft;
    R.outputwidth = opt_outputwidth;
    if (R.outputwidth < 1) R.outputwidth = 1;
    /* Determine smushmode */
    int effective_smushmode;
    if (opt_smushuser) {
        effective_smushmode = opt_smushmode;
    } else {
        effective_smushmode = ft->smushmode;
    }
    /* -s: if font has SM_SMUSH not set, use font as-is (kerning or full width).
       -S: force SM_SMUSH on top of font.
       Other flags (-k, -W, -o) already set by user via opt_smushuser. */
    if (opt_smushoverride == 2) {
        effective_smushmode |= SM_SMUSH;
    }
    R.smushmode = effective_smushmode;
    R.right2left = (opt_right2left == RTL_DEFAULT) ? ft->right2left : opt_right2left;
    /* Default justification: LTR=left, RTL=right */
    R.justification = opt_justification;
    if (R.justification == JUST_DEFAULT) {
        R.justification = R.right2left ? JUST_RIGHT : JUST_LEFT;
    }

    line_init(&R.outline, ft->charheight);
    R.prev_char = 0;
    R.at_start = 1;

    /* Build a list of input code points from argv or stdin */
    int *codes = NULL;
    int codes_len = 0, codes_cap = 256;
    codes = malloc(sizeof(int) * codes_cap);
    int need_nl_between_argv = 0;
    (void)need_nl_between_argv;

    #define ADD_CODE(c) do { \
        if (codes_len >= codes_cap) { codes_cap *= 2; codes = realloc(codes, sizeof(int)*codes_cap); } \
        codes[codes_len++] = (c); \
    } while (0)

    if (have_message) {
        for (int i = 0; i < argc_msg; i++) {
            if (i > 0) ADD_CODE('\n');  /* Each argv message adds a newline between */
            const char *s = argv_msg[i];
            while (*s) {
                int cp;
                if (input_mode == 'u') {
                    unsigned char b = (unsigned char)*s++;
                    int extra;
                    if ((b & 0x80) == 0) { cp = b; extra = 0; }
                    else if ((b & 0xE0) == 0xC0) { cp = b & 0x1F; extra = 1; }
                    else if ((b & 0xF0) == 0xE0) { cp = b & 0x0F; extra = 2; }
                    else if ((b & 0xF8) == 0xF0) { cp = b & 0x07; extra = 3; }
                    else { cp = b; extra = 0; }
                    for (int k = 0; k < extra && *s; k++) {
                        unsigned char nb = (unsigned char)*s++;
                        cp = (cp << 6) | (nb & 0x3F);
                    }
                } else {
                    cp = (unsigned char)*s++;
                }
                /* normalize whitespace */
                if (cp == '\t') cp = ' ';
                if (cp == '\r' || cp == '\v' || cp == '\f') cp = '\n';
                ADD_CODE(cp);
            }
        }
        /* Add final newline to terminate last line */
        ADD_CODE('\n');
    } else {
        /* Read from stdin, handling paragraph mode */
        int c;
        while ((c = read_input_char(stdin, &(int){0}, &(const char*){NULL})) != EOF) {
            ADD_CODE(c);
        }
        /* Ensure final newline */
        if (codes_len == 0 || codes[codes_len-1] != '\n') ADD_CODE('\n');
    }

    /* Apply translations and deutsch */
    for (int i = 0; i < codes_len; i++) {
        int c = codes[i];
        if (c != '\n') codes[i] = translate_char(c);
    }

    /* Paragraph mode: convert non-initial newlines (not followed by space/newline)
       to space.  Specifically, a newline that is not preceded by a newline and not
       followed by a space char becomes a space. */
    if (opt_paragraph) {
        for (int i = 0; i < codes_len; i++) {
            if (codes[i] == '\n') {
                int prev = (i > 0) ? codes[i-1] : '\n';
                int next = (i + 1 < codes_len) ? codes[i+1] : '\n';
                if (prev != '\n' && next != ' ' && next != '\n') {
                    codes[i] = ' ';
                }
            }
        }
    }

    /* If RTL, reverse the code sequence, keeping newline boundaries in relative order */
    if (R.right2left) {
        /* Reverse chunks between newlines separately, so lines stay in order */
        int start = 0;
        for (int i = 0; i <= codes_len; i++) {
            if (i == codes_len || codes[i] == '\n') {
                /* reverse codes[start..i-1] */
                for (int a = start, b = i - 1; a < b; a++, b--) {
                    int t = codes[a]; codes[a] = codes[b]; codes[b] = t;
                }
                start = i + 1;
            }
        }
    }

