    Line word;
    line_init(&word, ft->charheight);
    int pending_space = 0;  /* accumulated space count since last committed word */

    /* Helper to commit `word` into R.outline */
    #define COMMIT_WORD() do {                                         \
        if (word.len > 0) {                                             \
            /* Add pending space char(s), then word */                  \
            int ps = pending_space;                                      \
            pending_space = 0;                                           \
            /* Compute combined width */                                  \
            int combined_w;                                              \
            if (R.outline.len == 0) {                                    \
                combined_w = word.len;                                    \
            } else {                                                     \
                /* try: outline + ps spaces + word */                    \
                /* This is the trickiest part, approximate by chaining. */\
                FigChar *sp = find_figchar(ft, ' ');                     \
                Line tmp; line_init(&tmp, ft->charheight);                \
                /* copy outline to tmp */                                \
                line_ensure(&tmp, R.outline.len);                        \
                for (int r = 0; r < ft->charheight; r++) {                \
                    memcpy(tmp.rows[r], R.outline.rows[r], R.outline.len);\
                    tmp.rows[r][R.outline.len] = '\0';                     \
                }                                                        \
                tmp.len = R.outline.len;                                  \
                for (int s = 0; s < ps && sp; s++) do_append_fc(&tmp, sp, R.smushmode, ft->hardblank, 0); \
                /* Append word figchars one at a time from word.rows... \
                 * But word is a Line, not a figchar. Need line-append. */ \
                FigChar tmpfc; tmpfc.code = 0; tmpfc.width = word.len; \
                tmpfc.lines = word.rows; tmpfc.next = NULL; \
                do_append_fc(&tmp, &tmpfc, R.smushmode, ft->hardblank, 0); \
                combined_w = tmp.len;                                    \
                /* Decide fit */                                          \
                if (combined_w >= R.outputwidth) {                        \
                    /* Emit outline; outline = word (without space); */    \
                    save_line(&R.outline);                                  \
                    /* Copy word into outline */                            \
                    line_clear(&R.outline);                                 \
                    line_ensure(&R.outline, word.len);                      \
                    for (int r = 0; r < ft->charheight; r++) {              \
                        memcpy(R.outline.rows[r], word.rows[r], word.len);  \
                        R.outline.rows[r][word.len] = '\0';                 \
                    }                                                       \
                    R.outline.len = word.len;                               \
                } else {                                                   \
                    /* Accept: outline = tmp */                             \
                    line_clear(&R.outline);                                 \
                    line_ensure(&R.outline, tmp.len);                       \
                    for (int r = 0; r < ft->charheight; r++) {              \
                        memcpy(R.outline.rows[r], tmp.rows[r], tmp.len);    \
                        R.outline.rows[r][tmp.len] = '\0';                  \
                    }                                                       \
                    R.outline.len = tmp.len;                                 \
                }                                                           \
                line_free(&tmp);                                           \
                goto end_commit;                                            \
            }                                                              \
            /* outline empty: set outline = word */                       \
            line_ensure(&R.outline, word.len);                            \
            for (int r = 0; r < ft->charheight; r++) {                    \
                memcpy(R.outline.rows[r], word.rows[r], word.len);        \
                R.outline.rows[r][word.len] = '\0';                        \
            }                                                              \
            R.outline.len = word.len;                                      \
            end_commit: ;                                                   \
            line_clear(&word);                                              \
        }                                                                  \
    } while (0)

    for (int i = 0; i < codes_len; i++) {
        int c = codes[i];
        if (c == '\n') {
            COMMIT_WORD();
            pending_space = 0;
            save_line(&R.outline);
            continue;
        }
        if (c == ' ') {
            COMMIT_WORD();
            pending_space++;
            continue;
        }
        FigChar *fc = get_figchar(ft, c);
        if (!fc) continue;
        /* Try adding fc to word */
        int new_word_w = peek_append_width(&word, fc, R.smushmode, ft->hardblank, 0);
        if (new_word_w >= R.outputwidth) {
            /* Word overflow: emit outline, emit word, start fresh word */
            COMMIT_WORD();
            /* Emit outline */
            if (R.outline.len > 0) save_line(&R.outline);
            /* Emit current word (before adding c) */
            /* But word was just committed in COMMIT_WORD to outline; now outline has it. */
            /* save_line() already moved outline.  Start word=c. */
            pending_space = 0;
            do_append_fc(&word, fc, R.smushmode, ft->hardblank, 0);
        } else {
            do_append_fc(&word, fc, R.smushmode, ft->hardblank, 0);
        }
    }

    line_free(&word);
    line_free(&R.outline);

    /* If RTL, reverse list of rendered lines */
    int prepend_sp = R.right2left ? 1 : 0;
    if (R.right2left) reverse_render_list();
    flush_render_list(R.outputwidth, R.justification, ft->hardblank, prepend_sp);

    #undef COMMIT_WORD
    #undef ADD_CODE
    free(codes);
}

