/* Copy a Line's content into another Line */
static void line_copy(Line *dst, const Line *src) {
    line_ensure(dst, src->len);
    for (int r = 0; r < dst->height; r++) {
        memcpy(dst->rows[r], src->rows[r], src->len);
        dst->rows[r][src->len] = '\0';
    }
    dst->len = src->len;
}

/*
 * Append contents of src line to dst line, using smushing.
 * Treats src as a figchar whose lines are src->rows and width is src->len.
 */
static void do_append_line(Line *dst, const Line *src, int smushmode, char hardblank, int right2left) {
    if (src->len == 0) return;
    FigChar fc;
    fc.code = 0;
    fc.width = src->len;
    fc.lines = src->rows;
    fc.next = NULL;
    do_append_fc(dst, &fc, smushmode, hardblank, right2left);
}

static int peek_append_line_width(Line *dst, const Line *src, int smushmode, char hardblank, int right2left) {
    if (src->len == 0) return dst->len;
    FigChar fc;
    fc.code = 0;
    fc.width = src->len;
    fc.lines = src->rows;
    fc.next = NULL;
    return peek_append_width(dst, &fc, smushmode, hardblank, right2left);
}

/*
 * Rendering state
 */
typedef struct {
    Font *ft;
    int smushmode;
    int outputwidth;
    int justification;
    int right2left;
    Line outline;     /* committed line */
    Line word;        /* current word */
    int pending_space;
} RState;

/*
 * Commit `word` into `outline` using pending_space as number of space chars to insert
 * between them.  If the combined width would overflow, emit outline first, then
 * set outline = word.
 */
static void commit_word(RState *s) {
    if (s->word.len == 0) {
        return;
    }
    if (s->outline.len == 0) {
        /* Just copy word to outline */
        line_copy(&s->outline, &s->word);
        line_clear(&s->word);
        s->pending_space = 0;
        return;
    }
    /* Try: tmp = outline + (pending_space space chars) + word */
    Line tmp;
    line_init(&tmp, s->ft->charheight);
    line_copy(&tmp, &s->outline);
    FigChar *sp = find_figchar(s->ft, ' ');
    for (int i = 0; i < s->pending_space && sp; i++) {
        do_append_fc(&tmp, sp, s->smushmode, s->ft->hardblank, 0);
    }
    do_append_line(&tmp, &s->word, s->smushmode, s->ft->hardblank, 0);
    if (tmp.len >= s->outputwidth) {
        /* Emit outline; outline = word */
        save_line(&s->outline);
        line_copy(&s->outline, &s->word);
    } else {
        line_copy(&s->outline, &tmp);
    }
    line_clear(&s->word);
    s->pending_space = 0;
    line_free(&tmp);
}

/*
 * Emit outline (save it for later printing) and reset.
 */
