/*
 * Process a single (already-translated) input code point.
 */
static void process_char(RState *s, int c) {
    if (c == '\n') {
        commit_word(s);
        emit_outline(s);
        s->pending_space = 0;
        return;
    }
    if (c == ' ') {
        commit_word(s);
        s->pending_space++;
        return;
    }
    FigChar *fc = get_figchar(s->ft, c);
    if (!fc) return;
    int new_word_w = peek_append_width(&s->word, fc, s->smushmode, s->ft->hardblank, 0);
    if (new_word_w >= s->outputwidth) {
        /* Word would overflow.  Emit current outline (with word merged), emit word, start fresh */
        commit_word(s);
        if (s->outline.len > 0) emit_outline(s);
        s->pending_space = 0;
        /* word is already committed to outline (via commit_word), which was then emitted.
           So word should be empty here.  Start new word with c. */
        do_append_fc(&s->word, fc, s->smushmode, s->ft->hardblank, 0);
    } else {
        do_append_fc(&s->word, fc, s->smushmode, s->ft->hardblank, 0);
    }
}

static void process_finish(RState *s) {
    commit_word(s);
    if (s->outline.len > 0) emit_outline(s);
}

