/*
 * Read one Unicode code point from a FILE (UTF-8) or single byte (Latin-1).
 * Returns EOF on end.
 */
static int readcp(FILE *f) {
    if (input_mode == 'u') {
        int b = fgetc(f);
        if (b == EOF) return EOF;
        int cp, extra;
        if ((b & 0x80) == 0) { cp = b; extra = 0; }
        else if ((b & 0xE0) == 0xC0) { cp = b & 0x1F; extra = 1; }
        else if ((b & 0xF0) == 0xE0) { cp = b & 0x0F; extra = 2; }
        else if ((b & 0xF8) == 0xF0) { cp = b & 0x07; extra = 3; }
        else { cp = b; extra = 0; }
        for (int i = 0; i < extra; i++) {
            int nb = fgetc(f);
            if (nb == EOF) break;
            cp = (cp << 6) | (nb & 0x3F);
        }
        return cp;
    }
    int b = fgetc(f);
    if (b == EOF) return EOF;
    return b;
}

static void run_render(Font *ft, int argc_msg, char **argv_msg) {
    RState s;
    s.ft = ft;
    s.outputwidth = opt_outputwidth;
    if (s.outputwidth < 1) s.outputwidth = 1;

    /* Effective smushmode */
    int effective_smushmode;
    if (opt_smushuser) {
        effective_smushmode = opt_smushmode;
    } else {
        effective_smushmode = ft->smushmode;
    }
    if (opt_smushoverride == 2) {
        effective_smushmode |= SM_SMUSH;
    }
    s.smushmode = effective_smushmode;
    s.right2left = (opt_right2left == RTL_DEFAULT) ? ft->right2left : opt_right2left;
    s.justification = opt_justification;
    if (s.justification == JUST_DEFAULT) {
        s.justification = s.right2left ? JUST_RIGHT : JUST_LEFT;
    }
    line_init(&s.outline, ft->charheight);
    line_init(&s.word, ft->charheight);
    s.pending_space = 0;

    /* Collect all codes */
    int *codes = NULL;
    int codes_len = 0, codes_cap = 256;
    codes = malloc(sizeof(int) * codes_cap);
    #define ADD_CODE(c) do { \
        if (codes_len >= codes_cap) { codes_cap *= 2; codes = realloc(codes, sizeof(int)*codes_cap); } \
        codes[codes_len++] = (c); \
    } while (0)

    if (argc_msg > 0) {
        for (int i = 0; i < argc_msg; i++) {
            if (i > 0) ADD_CODE('\n');
            const char *p = argv_msg[i];
            while (*p) {
                int cp;
                if (input_mode == 'u') {
                    unsigned char b = (unsigned char)*p++;
                    int extra;
                    if ((b & 0x80) == 0) { cp = b; extra = 0; }
                    else if ((b & 0xE0) == 0xC0) { cp = b & 0x1F; extra = 1; }
                    else if ((b & 0xF0) == 0xE0) { cp = b & 0x0F; extra = 2; }
                    else if ((b & 0xF8) == 0xF0) { cp = b & 0x07; extra = 3; }
                    else { cp = b; extra = 0; }
                    for (int k = 0; k < extra && *p; k++) {
                        unsigned char nb = (unsigned char)*p++;
                        cp = (cp << 6) | (nb & 0x3F);
                    }
                } else {
                    cp = (unsigned char)*p++;
                }
                if (cp == '\t') cp = ' ';
                if (cp == '\r' || cp == '\v' || cp == '\f') cp = '\n';
                ADD_CODE(cp);
            }
        }
        ADD_CODE('\n');
    } else {
        int c;
        while ((c = readcp(stdin)) != EOF) {
            if (c == '\t') c = ' ';
            if (c == '\r' || c == '\v' || c == '\f') c = '\n';
            ADD_CODE(c);
        }
        if (codes_len == 0 || codes[codes_len-1] != '\n') ADD_CODE('\n');
    }

    /* Translate */
    for (int i = 0; i < codes_len; i++) {
        if (codes[i] != '\n') codes[i] = translate_char(codes[i]);
    }

    /* Paragraph mode */
    if (opt_paragraph) {
        for (int i = 0; i < codes_len; i++) {
            if (codes[i] == '\n') {
                int prev = (i > 0) ? codes[i-1] : '\n';
                int next = (i + 1 < codes_len) ? codes[i+1] : '\n';
                if (prev != '\n' && next != ' ' && next != '\n') {
                    codes[i] = ' ';
                }
            }
        }
    }

    /* Reverse for RTL */
    if (s.right2left) {
        int start = 0;
        for (int i = 0; i <= codes_len; i++) {
            if (i == codes_len || codes[i] == '\n') {
                for (int a = start, b = i - 1; a < b; a++, b--) {
                    int t = codes[a]; codes[a] = codes[b]; codes[b] = t;
                }
                start = i + 1;
            }
        }
    }

    for (int i = 0; i < codes_len; i++) {
        process_char(&s, codes[i]);
    }
    process_finish(&s);

    line_free(&s.outline);
    line_free(&s.word);

    int prepend_sp = s.right2left ? 1 : 0;
    if (s.right2left) reverse_render_list();
    flush_render_list(s.outputwidth, s.justification, ft->hardblank, prepend_sp);

    #undef ADD_CODE
    free(codes);
}

