static int get_terminal_width(void) {
    struct winsize w;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) == 0 && w.ws_col > 0) return w.ws_col;
    return -1;
}

int main(int argc, char **argv) {
    /* set progname from argv[0]'s basename */
    if (argc > 0) {
