        progname = b ? b + 1 : argv[0];
    }

    /* default font dir: FIGLET_FONTDIR or DEFAULT_FONTDIR */
    const char *envd = getenv("FIGLET_FONTDIR");
    if (envd) opt_fontdir = strdup(envd);

    int opt;
    opterr = 0;
    while ((opt = getopt(argc, argv, "cklnoprstvxDELNRSWXd:f:m:w:C:I:")) != -1) {
        switch (opt) {
            case 'c': opt_justification = JUST_CENTER; break;
            case 'k':
                opt_smushuser = 1;
                opt_smushmode = SM_KERN;
