            case 'n':
                opt_paragraph = 0;
                break;
            case 'o':
                opt_smushuser = 1;
                opt_smushmode = SM_SMUSH;  /* overlap (universal smushing) */
                break;
            case 'p': opt_paragraph = 1; break;
            case 'r': opt_justification = JUST_RIGHT; break;
            case 's': opt_smushoverride = 0; opt_smushuser = 0; break;
            case 't': opt_useterminalwidth = 1; {
                int t = get_terminal_width();
                if (t > 0) opt_outputwidth = t;
            } break;
            case 'v': opt_infocode = 0; break;
            case 'x': opt_justification = JUST_DEFAULT; break;
            case 'D': opt_deutsch = 1; break;
            case 'E': opt_deutsch = 0; break;
            case 'L': opt_right2left = RTL_LTR; break;
            case 'N': clear_cfiles(); break;
            case 'R': opt_right2left = RTL_RTL; break;
            case 'S':
                opt_smushoverride = 2;
                break;
            case 'W':
                opt_smushuser = 1;
                opt_smushmode = 0;  /* full width */
                break;
            case 'X': opt_right2left = RTL_DEFAULT; break;
            case 'd':
                if (opt_fontdir) free(opt_fontdir);
                opt_fontdir = strdup(optarg);
                break;
            case 'f':
                opt_fontname = strdup(optarg);
                /* strip .flf extension */
                {
                    char *dot = strrchr(opt_fontname, '.');
                    if (dot && strcmp(dot, ".flf") == 0) *dot = '\0';
                }
                break;
            case 'm':
                opt_smushuser = 1;
                opt_smushmode = atoi(optarg);
                if (opt_smushmode == 0) {
                    opt_smushmode = SM_KERN;
                } else if (opt_smushmode == -1) {
                    opt_smushmode = 0;  /* full width */
                } else if (opt_smushmode == -2) {
                    opt_smushuser = 0;  /* use font's smushmode (same as -s) */
                } else if (opt_smushmode > 0) {
                    /* Old-style: low 6 bits are rules, +SM_SMUSH */
                    if (opt_smushmode > 63) {
                        /* Out of range -> treat as kerning */
                        opt_smushmode = SM_KERN;
                    } else {
                        opt_smushmode = (opt_smushmode & 63) | SM_SMUSH;
                    }
                } else {
                    opt_smushmode = 0;
                }
                break;
            case 'w':
                opt_outputwidth_user = 1;
                {
                    int w = atoi(optarg);
                    if (w > 0) opt_outputwidth = w;
                }
