                break;
            case '?':
                /* invalid option */
                fprintf(stderr, "%s: invalid option -- '%c'\n", argv[0], optopt);
                print_usage(stderr);
                exit(1);
            default:
                print_usage(stderr);
                exit(1);
        }
    }

    /* Set defaults */
    if (!opt_fontname) opt_fontname = strdup(DEFAULT_FONT);
    /* Handle info codes BEFORE loading font */
    if (opt_infocode >= 0) {
        switch (opt_infocode) {
            case 0:
                print_version(stdout);
                return 0;
            case 1:
                printf("%d\n", 20205);
                return 0;
            case 2:
                printf("%s\n", opt_fontdir ? opt_fontdir : DEFAULT_FONTDIR);
                return 0;
            case 3:
                {
                    /* Print font name without path and without .flf */
                    char *name = opt_fontname;
                    const char *b = strrchr(name, '/');
                    const char *bn = b ? b + 1 : name;
                    char buf[4096];
                    strncpy(buf, bn, sizeof(buf)-1);
                    buf[sizeof(buf)-1] = '\0';
                    char *dot = strrchr(buf, '.');
                    if (dot && strcmp(dot, ".flf") == 0) *dot = '\0';
                    printf("%s\n", buf);
                }
                return 0;
            case 4:
                printf("%d\n", opt_outputwidth);
                return 0;
            case 5:
                printf("flf2 tlf2\n");
                return 0;
            default:
                return 0;
        }
    }

    /* Load font */
    Font *ft = load_font(opt_fontname, opt_fontdir ? opt_fontdir : DEFAULT_FONTDIR);

    /* Load control files (in order) */
    for (CFile *c = cfiles; c; c = c->next) {
        if (load_controlfile(c->path) < 0) {
            exit(1);
        }
    }

    /* Remaining args form the message (or read from stdin if none) */
    int n_msg = argc - optind;
    char **msg = argv + optind;

    run_render(ft, n_msg, msg);

    return 0;
}
