        /* Doesn't fit; emit existing outline, start new outline with spaces+word.
         * But we do NOT carry the pending spaces over (standard figlet discards
         * them at a wrap point). */
        save_line(&s->outline);
        line_clear(&s->outline);
        if (s->word.len > 0) {
            do_append_line(&s->outline, &s->word, s->smushmode, s->ft->hardblank, 0);
