static void line_pad_space(Line *l, int n) {
    if (n <= 0) return;
    line_ensure(l, l->len + n);
    for (int r = 0; r < l->height; r++) {
        for (int i = 0; i < n; i++) l->rows[r][l->len + i] = ' ';
        l->rows[r][l->len + n] = '\\0';
    }
    l->len += n;
