/*
 * Compute smushamt for prepending fc to the left side of out.
 * That is, smushing between fc's right edge and out's left edge.
 */
static int prepend_smushamt(Line *out, FigChar *fc, int smushmode, char hardblank, int right2left) {
    if (is_fullwidth(smushmode)) return 0;
    if (out->len == 0) {
        /* First char: trim common trailing spaces? No - trim common LEADING spaces to keep RTL left edge clean.
         * For single char, use same logic: trim leading common spaces. */
        int maxsmush = fc->width;
        for (int r = 0; r < out->height; r++) {
            int left_sp = 0;
            for (; left_sp < fc->width && fc->lines[r][left_sp] == ' '; left_sp++) ;
            if (left_sp < maxsmush) maxsmush = left_sp;
        }
        if (maxsmush < 0) maxsmush = 0;
        return maxsmush;
    }
    int maxsmush = fc->width;
    for (int r = 0; r < out->height; r++) {
        int curlen = out->len;
        const char *cur = out->rows[r];
        const char *newf = fc->lines[r];
        int newlen = fc->width;

        /* Looking at fc's right edge and cur's left edge */
        int right_sp;  /* trailing spaces of fc */
        for (right_sp = 0; right_sp < newlen && newf[newlen - 1 - right_sp] == ' '; right_sp++) ;
        int left_sp;   /* leading spaces of cur */
        for (left_sp = 0; left_sp < curlen && cur[left_sp] == ' '; left_sp++) ;

        int a = left_sp + right_sp;
        int ch1 = (right_sp < newlen) ? (unsigned char)newf[newlen - 1 - right_sp] : 0;
        int ch2 = (left_sp < curlen) ? (unsigned char)cur[left_sp] : 0;
        if (ch1 != 0 && ch2 != 0) {
            int s = smushem(ch1, ch2, smushmode, hardblank, right2left);
            if (s != 0) a += 1;
        }
        if (a < maxsmush) maxsmush = a;
    }
    if (maxsmush < 0) maxsmush = 0;
    return maxsmush;
}

/*
 * Peek width if we were to prepend fc to out.
 */
static int peek_prepend_width(Line *out, FigChar *fc, int smushmode, char hardblank, int right2left) {
    if (is_fullwidth(smushmode)) return out->len + fc->width;
    if (out->len == 0) {
        int maxsmush = fc->width;
        for (int r = 0; r < out->height; r++) {
            int left_sp = 0;
            for (; left_sp < fc->width && fc->lines[r][left_sp] == ' '; left_sp++) ;
            if (left_sp < maxsmush) maxsmush = left_sp;
        }
        if (maxsmush < 0) maxsmush = 0;
        return fc->width - maxsmush;
    }
    int amt = prepend_smushamt(out, fc, smushmode, hardblank, right2left);
    return out->len + fc->width - amt;
}

/*
 * Prepend fc to out (smushing at left boundary).
 */
static void do_prepend_fc(Line *out, FigChar *fc, int smushmode, char hardblank, int right2left) {
    if (is_fullwidth(smushmode)) {
        /* No overlap.  Shift out right by fc->width, then place fc at left. */
        int newlen = out->len + fc->width;
        line_ensure(out, newlen);
        for (int r = 0; r < out->height; r++) {
            /* Shift existing content right */
            for (int i = out->len - 1; i >= 0; i--) {
                out->rows[r][i + fc->width] = out->rows[r][i];
            }
            /* Place fc at positions [0, fc->width) */
            for (int i = 0; i < fc->width; i++) out->rows[r][i] = fc->lines[r][i];
            out->rows[r][newlen] = '\0';
        }
        out->len = newlen;
        return;
    }
    int amt;
    if (out->len == 0) {
        /* First char placement: same trim as append case. */
        int maxsmush = fc->width;
        for (int r = 0; r < out->height; r++) {
            int left_sp = 0;
            for (; left_sp < fc->width && fc->lines[r][left_sp] == ' '; left_sp++) ;
            if (left_sp < maxsmush) maxsmush = left_sp;
        }
        if (maxsmush < 0) maxsmush = 0;
        amt = maxsmush;
        int newlen = fc->width - amt;
        line_ensure(out, newlen);
        for (int r = 0; r < out->height; r++) {
            for (int i = amt; i < fc->width; i++) {
                out->rows[r][i - amt] = fc->lines[r][i];
            }
            out->rows[r][newlen] = '\0';
        }
        out->len = newlen;
        return;
    }
    amt = prepend_smushamt(out, fc, smushmode, hardblank, right2left);
    int newlen = out->len + fc->width - amt;
    line_ensure(out, newlen);
    /* Shift existing content right by (fc->width - amt) */
    int shift = fc->width - amt;
    for (int r = 0; r < out->height; r++) {
        for (int i = out->len - 1; i >= 0; i--) {
            out->rows[r][i + shift] = out->rows[r][i];
        }
        /* Place fc at positions [0, fc->width).  The overlap region is [fc->width - amt, fc->width). */
        for (int i = 0; i < fc->width - amt; i++) {
            out->rows[r][i] = fc->lines[r][i];
        }
        /* Handle overlap: columns [fc->width - amt, fc->width) of fc overlap with
         * columns [0, amt) of the (shifted) cur row. Merge via smushing. */
        for (int i = 0; i < amt; i++) {
            int L = (unsigned char)fc->lines[r][(fc->width - amt) + i];
            int R = (unsigned char)out->rows[r][shift + i];
            int result;
            if (L == ' ') result = R;
            else if (R == ' ') result = L;
            else {
                result = smushem(L, R, smushmode, hardblank, right2left);
                if (result == 0) result = R;
            }
            out->rows[r][(fc->width - amt) + i] = (char)result;
        }
        out->rows[r][newlen] = '\0';
    }
    out->len = newlen;
}

/* Prepend an entire Line (as a virtual figchar) to another Line. */
static void do_prepend_line(Line *dst, const Line *src, int smushmode, char hardblank, int right2left) {
    if (src->len == 0) return;
    FigChar fc;
    fc.code = 0;
    fc.width = src->len;
    fc.lines = src->rows;
    fc.next = NULL;
    do_prepend_fc(dst, &fc, smushmode, hardblank, right2left);
}

static int peek_prepend_line_width(Line *dst, const Line *src, int smushmode, char hardblank, int right2left) {
    if (src->len == 0) return dst->len;
    FigChar fc;
    fc.code = 0;
