    test_it "$a" "$msg"
  done
done
for w in 1 5 10 15 20 25 30 40 80; do
  for msg in "hello world" "hi" "a" "hi there" "x" "abc def ghi"; do
    test_it "-w $w" "$msg"
    test_it "-R -w $w" "$msg"
  done
done
for f in standard small banner big slant shadow block mini script term smshadow smscript smslant lean digital bubble; do
  test_it "-f $f" "hello"
  test_it "-f $f" "Hi World"
  test_it "-f $f" "A B C"
  test_it "-f $f -c -w 40" "hello"
done
test_it "-C upper" "hello"
test_it "-C upper -N" "hello"
test_it "-D" "[\\\\]{|}~"
test_it "-R -f ivrit" "hello"
echo "Done. FAIL=$FAIL"

